ALTER TYPE tesoreria.dues_agreement_kind ADD VALUE IF NOT EXISTS 'NEGOTIATED';

ALTER TABLE tesoreria.dues_agreements ADD COLUMN IF NOT EXISTS terms_version integer NOT NULL DEFAULT 0;

DO $$ BEGIN ALTER TABLE tesoreria.dues_agreements ADD CONSTRAINT dues_agreements_terms_version_check CHECK (terms_version >= 0); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

ALTER TABLE tesoreria.dues_community_work ADD COLUMN IF NOT EXISTS agreement_id uuid;

DO $$ BEGIN ALTER TABLE tesoreria.dues_community_work ADD CONSTRAINT dues_community_work_agreement_fk FOREIGN KEY (agreement_id) REFERENCES tesoreria.dues_agreements(id) ON DELETE RESTRICT; EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE OR REPLACE FUNCTION tesoreria.validate_dues_agreement_evidence(value jsonb) RETURNS void LANGUAGE plpgsql AS $$ DECLARE reference_value jsonb; BEGIN IF jsonb_typeof(value) IS DISTINCT FROM 'object' OR octet_length(value::text) > 16384 THEN RAISE EXCEPTION 'agreement evidence is outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; IF EXISTS ( SELECT 1 FROM jsonb_object_keys(value) AS key_name WHERE key_name NOT IN ('note', 'references', 'metadata') ) THEN RAISE EXCEPTION 'agreement evidence contains an unsupported field' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; IF value ? 'note' AND ( jsonb_typeof(value->'note') IS DISTINCT FROM 'string' OR char_length(value->>'note') > 2000 ) THEN RAISE EXCEPTION 'agreement evidence note is outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; IF value ? 'references' THEN IF jsonb_typeof(value->'references') IS DISTINCT FROM 'array' OR jsonb_array_length(value->'references') > 50 THEN RAISE EXCEPTION 'agreement evidence references are outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; FOR reference_value IN SELECT reference_json FROM jsonb_array_elements(value->'references') AS references_json(reference_json) LOOP IF jsonb_typeof(reference_value) IS DISTINCT FROM 'string' OR char_length(reference_value #>> '{}') = 0 OR char_length(reference_value #>> '{}') > 500 THEN RAISE EXCEPTION 'agreement evidence reference is outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; END LOOP; END IF; IF value ? 'metadata' AND ( jsonb_typeof(value->'metadata') IS DISTINCT FROM 'object' OR octet_length((value->'metadata')::text) > 8192 ) THEN RAISE EXCEPTION 'agreement evidence metadata is outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; END $$;

CREATE OR REPLACE FUNCTION tesoreria.validate_dues_agreement() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE obligation_socio uuid; obligation_amount numeric; outstanding numeric; parent_obligation uuid; parent_revision_number integer; installment jsonb; commitment jsonb; agreed_cents bigint; installment_cents bigint; commitment_amount_cents bigint; installment_sum bigint := 0; previous_due_date date; due_date date; commitment_due_date date; BEGIN IF NEW.kind IN ('SIMPLE', 'INSTALLMENT') AND NEW.terms_version = 0 THEN IF jsonb_typeof(NEW.terms) IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.terms->'installments') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.terms->'installments') NOT BETWEEN 1 AND 60 OR (NEW.terms->>'amountCents') IS NULL OR (NEW.terms->>'amountCents') !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'agreement terms are outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; agreed_cents := (NEW.terms->>'amountCents')::bigint; IF agreed_cents > 99999999999999 THEN RAISE EXCEPTION 'agreement amount exceeds supported money range' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; FOR installment IN SELECT value FROM jsonb_array_elements(NEW.terms->'installments') LOOP IF jsonb_typeof(installment) IS DISTINCT FROM 'object' OR (installment->>'amountCents') IS NULL OR (installment->>'amountCents') !~ '^[1-9][0-9]*$' OR (installment->>'dueDate') IS NULL OR (installment->>'dueDate') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'agreement installment is invalid' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; installment_cents := (installment->>'amountCents')::bigint; due_date := (installment->>'dueDate')::date; IF due_date::text <> installment->>'dueDate' OR due_date < NEW.agreement_date OR (previous_due_date IS NOT NULL AND due_date <= previous_due_date) THEN RAISE EXCEPTION 'agreement installment dates must be valid, ordered, and on or after the agreement date' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; installment_sum := installment_sum + installment_cents; previous_due_date := due_date; END LOOP; IF installment_sum <> agreed_cents THEN RAISE EXCEPTION 'agreement installments must sum to the agreed amount' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; ELSIF NEW.kind = 'NEGOTIATED' AND NEW.terms_version = 1 THEN IF jsonb_typeof(NEW.terms) IS DISTINCT FROM 'object' OR EXISTS ( SELECT 1 FROM jsonb_object_keys(NEW.terms) AS key_name WHERE key_name NOT IN ('narrative', 'commitments', 'evidence') ) OR jsonb_typeof(NEW.terms->'narrative') IS DISTINCT FROM 'string' OR char_length(NEW.terms->>'narrative') NOT BETWEEN 1 AND 4000 OR btrim(NEW.terms->>'narrative') = '' THEN RAISE EXCEPTION 'negotiated agreement narrative is outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; IF NEW.terms ? 'evidence' THEN PERFORM tesoreria.validate_dues_agreement_evidence(NEW.terms->'evidence'); END IF; IF NEW.terms ? 'commitments' THEN IF jsonb_typeof(NEW.terms->'commitments') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.terms->'commitments') > 50 THEN RAISE EXCEPTION 'negotiated agreement commitments are outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; FOR commitment IN SELECT value FROM jsonb_array_elements(NEW.terms->'commitments') LOOP IF jsonb_typeof(commitment) IS DISTINCT FROM 'object' OR EXISTS ( SELECT 1 FROM jsonb_object_keys(commitment) AS key_name WHERE key_name NOT IN ('id', 'title', 'description', 'dueDate', 'amountCents', 'evidence') ) OR jsonb_typeof(commitment->'id') IS DISTINCT FROM 'string' OR (commitment->>'id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR jsonb_typeof(commitment->'title') IS DISTINCT FROM 'string' OR char_length(btrim(commitment->>'title')) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'negotiated agreement commitment is invalid' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; IF commitment ? 'description' AND ( jsonb_typeof(commitment->'description') IS DISTINCT FROM 'string' OR char_length(commitment->>'description') > 2000 ) THEN RAISE EXCEPTION 'negotiated agreement commitment description is outside the approved bounds' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; IF commitment ? 'dueDate' THEN IF jsonb_typeof(commitment->'dueDate') IS DISTINCT FROM 'string' OR (commitment->>'dueDate') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'negotiated agreement commitment date is invalid' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; commitment_due_date := to_date(commitment->>'dueDate', 'YYYY-MM-DD'); IF to_char(commitment_due_date, 'YYYY-MM-DD') IS DISTINCT FROM commitment->>'dueDate' THEN RAISE EXCEPTION 'negotiated agreement commitment date is invalid' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; END IF; IF commitment ? 'amountCents' THEN IF jsonb_typeof(commitment->'amountCents') IS DISTINCT FROM 'number' OR (commitment->>'amountCents') !~ '^[1-9][0-9]*$' OR char_length(commitment->>'amountCents') > 14 THEN RAISE EXCEPTION 'negotiated agreement commitment amount is invalid' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; commitment_amount_cents := (commitment->>'amountCents')::bigint; IF commitment_amount_cents > 99999999999999 THEN RAISE EXCEPTION 'negotiated agreement commitment amount is invalid' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; END IF; IF commitment ? 'evidence' THEN PERFORM tesoreria.validate_dues_agreement_evidence(commitment->'evidence'); END IF; END LOOP; END IF; ELSE RAISE EXCEPTION 'agreement kind and terms version are unsupported' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_terms_check'; END IF; SELECT socio_id, amount INTO obligation_socio, obligation_amount FROM tesoreria.dues_obligations WHERE id = NEW.obligation_id FOR UPDATE; IF obligation_socio IS NULL OR obligation_socio IS DISTINCT FROM NEW.socio_id THEN RAISE EXCEPTION 'agreement obligation does not belong to the socio' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_obligation_owner_check'; END IF; IF NEW.kind IN ('SIMPLE', 'INSTALLMENT') THEN SELECT obligation_amount - COALESCE(SUM(CASE WHEN kind = 'ALLOCATION' THEN amount ELSE -amount END), 0) INTO outstanding FROM tesoreria.dues_allocations WHERE obligation_id = NEW.obligation_id; IF agreed_cents > (COALESCE(outstanding, obligation_amount) * 100)::bigint THEN RAISE EXCEPTION 'agreement amount exceeds outstanding obligation debt' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_outstanding_check'; END IF; END IF; IF NEW.revision_of_agreement_id IS NULL THEN IF NEW.revision_number <> 1 THEN RAISE EXCEPTION 'root agreement must have revision number 1' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_revision_number_check'; END IF; ELSE SELECT obligation_id, revision_number INTO parent_obligation, parent_revision_number FROM tesoreria.dues_agreements WHERE id = NEW.revision_of_agreement_id; IF parent_obligation IS DISTINCT FROM NEW.obligation_id OR NEW.revision_number <> parent_revision_number + 1 THEN RAISE EXCEPTION 'agreement revision must preserve obligation identity and increment revision number' USING ERRCODE = '23514', CONSTRAINT = 'dues_agreements_revision_obligation_check'; END IF; END IF; RETURN NEW; END $$;

CREATE OR REPLACE FUNCTION tesoreria.validate_dues_community_work() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE settlement_socio uuid; settlement_kind tesoreria.dues_settlement_kind; settlement_amount numeric; obligation_socio uuid; agreement_socio uuid; agreement_obligation uuid; BEGIN SELECT socio_id, kind, amount INTO settlement_socio, settlement_kind, settlement_amount FROM tesoreria.dues_settlements WHERE id = NEW.settlement_id; SELECT socio_id INTO obligation_socio FROM tesoreria.dues_obligations WHERE id = NEW.obligation_id; IF settlement_kind IS DISTINCT FROM 'NON_CASH' OR settlement_socio IS DISTINCT FROM NEW.socio_id OR obligation_socio IS DISTINCT FROM NEW.socio_id OR settlement_amount IS DISTINCT FROM NEW.amount THEN RAISE EXCEPTION 'community work must reference a matching non-cash settlement and obligation' USING ERRCODE = '23514', CONSTRAINT = 'dues_community_work_settlement_check'; END IF; IF NEW.agreement_id IS NOT NULL THEN SELECT socio_id, obligation_id INTO agreement_socio, agreement_obligation FROM tesoreria.dues_agreements WHERE id = NEW.agreement_id; IF agreement_socio IS DISTINCT FROM NEW.socio_id OR agreement_obligation IS DISTINCT FROM NEW.obligation_id THEN RAISE EXCEPTION 'community work agreement must match the socio and obligation' USING ERRCODE = '23514', CONSTRAINT = 'dues_community_work_agreement_check'; END IF; END IF; RETURN NEW; END $$;

CREATE OR REPLACE FUNCTION tesoreria.reject_dues_agreement_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_TABLE_NAME = 'dues_agreements' AND OLD.status = 'ACTIVE' AND NEW.status = 'SUPERSEDED' AND OLD.socio_id IS NOT DISTINCT FROM NEW.socio_id AND OLD.obligation_id IS NOT DISTINCT FROM NEW.obligation_id AND OLD.kind IS NOT DISTINCT FROM NEW.kind AND OLD.terms_version IS NOT DISTINCT FROM NEW.terms_version AND OLD.revision_number IS NOT DISTINCT FROM NEW.revision_number AND OLD.terms IS NOT DISTINCT FROM NEW.terms AND OLD.reason IS NOT DISTINCT FROM NEW.reason AND OLD.revision_of_agreement_id IS NOT DISTINCT FROM NEW.revision_of_agreement_id AND OLD.revision_reason IS NOT DISTINCT FROM NEW.revision_reason AND OLD.operator_id IS NOT DISTINCT FROM NEW.operator_id AND OLD.authorization_evidence IS NOT DISTINCT FROM NEW.authorization_evidence AND OLD.caller_key IS NOT DISTINCT FROM NEW.caller_key AND OLD.request_fingerprint IS NOT DISTINCT FROM NEW.request_fingerprint AND OLD.agreement_date IS NOT DISTINCT FROM NEW.agreement_date AND OLD.created_at IS NOT DISTINCT FROM NEW.created_at THEN RETURN NEW; END IF; RAISE EXCEPTION 'dues agreements and community work are immutable' USING ERRCODE = '55000'; END $$;
